/* ============================================================
   js/vendor/notosans-vietnamese-jspdf.js
   Font Unicode (Noto Sans, subset Latin + tiếng Việt) nhúng vào jsPDF
   để xuất PDF hiển thị đúng dấu tiếng Việt — font mặc định của jsPDF
   (helvetica/times/courier) chỉ hỗ trợ WinAnsi (Latin-1), làm sai dấu
   tiếng Việt (vd "Lịch giảng dạy" bị in ra "LËch giÊng dfy").

   Nguồn: Google Noto Sans (SIL Open Font License 1.1) — lấy bản
   variable font từ google/fonts, dùng fontTools.varLib.instancer chốt
   về 2 bản tĩnh (Regular wght=400, Bold wght=700), rồi fontTools.subset
   rút gọn chỉ còn Latin cơ bản + Latin-1 Supplement + Latin Extended-A/B
   (có đủ ư/ơ + toàn bộ nguyên âm có dấu tiếng Việt ở Latin Extended
   Additional) + 1 số dấu câu thường dùng — ~105KB/file thay vì ~650KB
   bản đầy đủ, không ảnh hưởng nội dung khác trong app.

   Đăng ký theo đúng cơ chế chính thức của jsPDF (jsPDF.API.events) —
   mỗi jsPDF() instance mới tạo ra sẽ TỰ ĐỘNG có sẵn font "NotoSans".
   Nạp SAU js/vendor/jspdf.umd.min.js, TRƯỚC code gọi doc.setFont(...).
   ============================================================ */
(function () {
  'use strict';
  if (typeof window.jspdf === 'undefined' || !window.jspdf.jsPDF) return;

  var REGULAR_B64 = '';
  var BOLD_B64 = '';

  window.jspdf.jsPDF.API.events.push(['addFonts', function () {
    this.addFileToVFS('NotoSans-Regular.ttf', REGULAR_B64);
    this.addFont('NotoSans-Regular.ttf', 'NotoSans', 'normal');
    this.addFileToVFS('NotoSans-Bold.ttf', BOLD_B64);
    this.addFont('NotoSans-Bold.ttf', 'NotoSans', 'bold');
  }]);
})();
